package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the sheet's settings: its clerk limit, its floor, its terms and each grade's, its late percent, its cap and its proof threshold, each
 * dated (kept from a from-date); and its policy date and its period numbering from, not dated.
 */
@Service
public class SettingService {

    /** The grades that may have their own terms. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;

    public SettingService(SheetRepository sheets, Audit audit, RollupService rollup) {
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    public Sheet get(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
    }

    /**
     * Set the clerk limit from the date (null: the sheet's today); a null limit means no limit. Every save is
     * recorded, even of the same value.
     */
    @Transactional
    public Sheet setClerkLimit(String sheetId, String user, BigDecimal limit, LocalDate from) {
        return record(sheetId, user, Sheet.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /**
     * Set the floor, the least a live due of a claim dated from the date (null: the sheet's today) can be. Every save
     * is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setFloor(String sheetId, String user, BigDecimal floor, LocalDate from) {
        return record(sheetId, user, Sheet.FLOOR, floor.toPlainString(), from, true);
    }

    /**
     * Set the terms from the date (null: the sheet's today), the days after its date a claim dated from then of a grade
     * without its own terms is due by. Every save is recorded, even of the same value. Claims already added keep their
     * due-by.
     */
    @Transactional
    public Sheet setTerms(String sheetId, String user, int terms, LocalDate from) {
        return record(sheetId, user, Sheet.TERMS, String.valueOf(terms), from, false);
    }

    /** The grades with their own terms in force on the sheet's today, in grade order; a grade not in it uses the sheet's terms. */
    public Map<String, Integer> gradeTerms(Sheet sheet) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        for (String grade : GRADES) {
            sheet.gradeTermsOn(grade, sheet.getToday()).ifPresent(t -> terms.put(grade, t));
        }
        return terms;
    }

    /** The terms in force for a claim dated on the date of a person of the grade: the grade's own, else the sheet's. */
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return get(sheetId).termsFor(grade, date);
    }

    /**
     * Set a grade's own terms from the date (null: the sheet's today). Every save is recorded, even of the same value.
     * Claims already added keep their due-by.
     */
    @Transactional
    public Sheet setGradeTerms(String sheetId, String user, String grade, int terms, LocalDate from) {
        return record(sheetId, user, Sheet.gradeTermsKey(grade), String.valueOf(terms), from, false);
    }

    /**
     * Set the late percent from the date (null: the sheet's today), what an overdue claim dated from then gains for
     * every full 30 days it is overdue. Every save is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setLatePct(String sheetId, String user, BigDecimal latePct, LocalDate from) {
        return record(sheetId, user, Sheet.LATE_PCT, latePct.toPlainString(), from, true);
    }

    /**
     * Set the cap from the date (null: the sheet's today), the most a person's due-total can be; a null cap means
     * none. Every save is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setCap(String sheetId, String user, BigDecimal cap, LocalDate from) {
        return record(sheetId, user, Sheet.CAP, cap == null ? null : cap.toPlainString(), from, true);
    }

    /**
     * Set the proof threshold from the date (null: the sheet's today): a claim dated from then whose due is above it
     * cannot be settled or approved without a proof; a null threshold means none. Every save is recorded, even of the
     * same value.
     */
    @Transactional
    public Sheet setProofThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
        return record(sheetId, user, Sheet.PROOF_THRESHOLD, threshold == null ? null : threshold.toPlainString(), from,
                false);
    }

    /**
     * Record a dated setting's value from the date (null: the sheet's today), replacing one recorded from that date,
     * then the SETTING_CHANGED record (with the from-date when one was given) and, when the setting moves figures,
     * the figures it moved.
     */
    private Sheet record(String sheetId, String user, String key, String value, LocalDate from, boolean movesFigures) {
        Sheet sheet = get(sheetId);
        RollupService.Snapshot before = movesFigures ? rollup.snapshot(sheetId) : null;
        sheet.record(key, from != null ? from : sheet.getToday(), value);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value="
                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (movesFigures) {
            rollup.recordChanges(sheetId, user, before);
        }
        return saved;
    }
    /**
     * Set the policy date, which decides how each claim's live figures round; null means the sheet's today. Every save
     * is recorded, even of the same value, then the figures it moved.
     */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String user, LocalDate policyDate) {
        Sheet sheet = get(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=policy-date value="
                + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Set the period numbering from; null means off. Every save is recorded, even of the same value. Claims already
     * opened keep their numbers.
     */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String user, LocalDate from) {
        Sheet sheet = get(sheetId);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
        return saved;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The sheet's settings. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/settings")
@Validated
public class SettingController {

    /**
     * The settings as shown, each dated one as in force on the sheet's today: the clerk limit with two decimals, null
     * when there is none; the floor with two decimals; the terms in whole days; each grade's own terms in whole days,
     * by grade (a grade without its own is left out); the late percent with two decimals; the policy date as
     * yyyy-mm-dd, null when blank (the sheet's today); the period numbering from as yyyy-mm-dd, null when blank (off);
     * the cap with two decimals, null when there is none; the proof threshold with two decimals, null when there is none.
     * Then every value recorded of each dated setting, by key (clerk-limit, floor, terms, terms-A, terms-B, terms-C,
     * late-pct, cap, proof-threshold), from-date first to last.
     */
    public record SettingsView(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms,
            String latePct, LocalDate policyDate, LocalDate periodNumberingFrom, String cap,
            String proofThreshold, Map<String, List<DatedValue>> dated) {

        static SettingsView of(Sheet sheet, Map<String, Integer> gradeTerms) {
            LocalDate today = sheet.getToday();
            Map<String, List<DatedValue>> dated = new LinkedHashMap<>();
            sheet.datedSettings().forEach((key, values) -> dated.put(key,
                    values.stream().map(d -> new DatedValue(d.getFromDate(), d.getValue())).toList()));
            return new SettingsView(shown(sheet.getClerkLimit()), shown(sheet.floorOn(today)), sheet.termsOn(today),
                    gradeTerms, shown(sheet.latePctOn(today)), sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(),
                    shown(sheet.getCap()), shown(sheet.proofThresholdOn(today)), dated);
        }

        private static String shown(BigDecimal value) {
            return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A dated setting's value (null: none) from its from-date. */
    public record DatedValue(LocalDate from, String value) {
    }

    /**
     * A clerk limit of 0.00 or more with up to two decimals, blank or missing meaning no limit, from the date (missing:
     * the sheet's today).
     */
    public record SettingsRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String clerkLimit,
            LocalDate from) {

        BigDecimal clerkLimitValue() {
            return clerkLimit == null || clerkLimit.isBlank() ? null
                    : new BigDecimal(clerkLimit.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** A floor of 0.00 or more with up to two decimals, from the date (missing: the sheet's today). */
    public record FloorRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String floor,
            LocalDate from) {

        BigDecimal floorValue() {
            return new BigDecimal(floor.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** Terms of 0 or more whole days, from the date (missing: the sheet's today). */
    public record TermsRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,5}\\s*") String terms,
            LocalDate from) {

        int termsValue() {
            return Integer.parseInt(terms.trim());
        }
    }

    /** A late percent of 0.00 or more with up to two decimals, from the date (missing: the sheet's today). */
    public record LatePctRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String latePct,
            LocalDate from) {

        BigDecimal latePctValue() {
            return new BigDecimal(latePct.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /**
     * A cap of 0.00 or more with up to two decimals, blank or missing meaning no cap, from the date (missing: the
     * sheet's today).
     */
    public record CapRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String cap,
            LocalDate from) {

        BigDecimal capValue() {
            return cap == null || cap.isBlank() ? null
                    : new BigDecimal(cap.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /**
     * A proof threshold of 0.00 or more with up to two decimals, blank or missing meaning none, from the date
     * (missing: the sheet's today).
     */
    public record ProofThresholdRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String proofThreshold,
            LocalDate from) {

        BigDecimal proofThresholdValue() {
            return proofThreshold == null || proofThreshold.isBlank() ? null
                    : new BigDecimal(proofThreshold.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** A policy date as yyyy-mm-dd; null (blank) means the sheet's today. */
    public record PolicyDateRequest(LocalDate policyDate) {
    }

    /** A period numbering from as yyyy-mm-dd; null (blank) means off. */
    public record PeriodNumberingFromRequest(LocalDate periodNumberingFrom) {
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping
    public SettingsView get(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.get(sheetId.trim()));
    }

    @PutMapping
    public SettingsView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid SettingsRequest request) {
        return view(service.setClerkLimit(sheetId.trim(), user.trim(), request.clerkLimitValue(), request.from()));
    }

    @PutMapping("/floor")
    public SettingsView setFloor(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid FloorRequest request) {
        return view(service.setFloor(sheetId.trim(), user.trim(), request.floorValue(), request.from()));
    }

    @PutMapping("/terms")
    public SettingsView setTerms(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TermsRequest request) {
        return view(service.setTerms(sheetId.trim(), user.trim(), request.termsValue(), request.from()));
    }

    @PutMapping("/terms/{grade}")
    public SettingsView setGradeTerms(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TermsRequest request) {
        return view(service.setGradeTerms(sheetId.trim(), user.trim(), grade, request.termsValue(), request.from()));
    }

    @PutMapping("/late-pct")
    public SettingsView setLatePct(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid LatePctRequest request) {
        return view(service.setLatePct(sheetId.trim(), user.trim(), request.latePctValue(), request.from()));
    }

    @PutMapping("/policy-date")
    public SettingsView setPolicyDate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody PolicyDateRequest request) {
        return view(service.setPolicyDate(sheetId.trim(), user.trim(), request.policyDate()));
    }

    @PutMapping("/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody PeriodNumberingFromRequest request) {
        return view(service.setPeriodNumberingFrom(sheetId.trim(), user.trim(), request.periodNumberingFrom()));
    }

    @PutMapping("/cap")
    public SettingsView setCap(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid CapRequest request) {
        return view(service.setCap(sheetId.trim(), user.trim(), request.capValue(), request.from()));
    }

    @PutMapping("/proof-threshold")
    public SettingsView setProofThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ProofThresholdRequest request) {
        return view(service.setProofThreshold(sheetId.trim(), user.trim(), request.proofThresholdValue(),
                request.from()));
    }

    private SettingsView view(Sheet sheet) {
        return SettingsView.of(sheet, service.gradeTerms(sheet));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;

/** A sheet: everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The keys of the dated settings: each value is kept from its from-date. */
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The sheet's starting values, in force before a key's first from-date: none for a key not listed. */
    private static final Map<String, String> STARTING = Map.of(FLOOR, "1.00", TERMS, "14", LATE_PCT, "0.00");

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's own today: every date-dependent decision and default date uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The values of the dated settings (the clerk limit, the floor, the terms and each grade's, the late percent,
     *  the cap and the proof threshold), each from its from-date. */
    @OneToMany(mappedBy = "sheet", fetch = FetchType.EAGER, cascade = CascadeType.ALL)
    @OrderBy("key ASC, fromDate ASC")
    private List<DatedSetting> dated = new ArrayList<>();

    /** The policy date: a claim dated before it rounds half up, one on or after it half to even; null: the today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** From this date (on the sheet's today) a claim opened is numbered within its period; null: off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** The key of a grade's own terms. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /**
     * Record a dated setting's value from the date (null: no limit or cap), replacing the value already recorded from
     * that date; the other values recorded are kept.
     */
    public void record(String key, LocalDate from, String value) {
        dated.stream().filter(d -> d.getKey().equals(key) && d.getFromDate().equals(from)).findFirst()
                .ifPresentOrElse(d -> d.setValue(value), () -> dated.add(new DatedSetting(this, key, from, value)));
    }

    /** Each dated setting's recorded values by key, from-date first to last. */
    public Map<String, List<DatedSetting>> datedSettings() {
        Map<String, List<DatedSetting>> byKey = new TreeMap<>();
        dated.stream().sorted(Comparator.comparing(DatedSetting::getFromDate))
                .forEach(d -> byKey.computeIfAbsent(d.getKey(), k -> new ArrayList<>()).add(d));
        return byKey;
    }

    /**
     * The value of a dated setting in force on the date: the one with the latest from-date on or before it, else the
     * sheet's starting value; empty when that is none.
     */
    public Optional<String> valueOn(String key, LocalDate date) {
        return dated.stream()
                .filter(d -> d.getKey().equals(key) && !d.getFromDate().isAfter(date))
                .max(Comparator.comparing(DatedSetting::getFromDate))
                .map(d -> Optional.ofNullable(d.getValue()))
                .orElseGet(() -> Optional.ofNullable(STARTING.get(key)));
    }

    private Optional<BigDecimal> decimalOn(String key, LocalDate date) {
        return valueOn(key, date).map(v -> new BigDecimal(v).setScale(2, RoundingMode.UNNECESSARY));
    }

    /** The highest due a clerk may settle, in force on the sheet's today; null when there is no limit. */
    public BigDecimal getClerkLimit() {
        return decimalOn(CLERK_LIMIT, today).orElse(null);
    }

    /** The least a live due of a claim dated on the date can be. */
    public BigDecimal floorOn(LocalDate date) {
        return decimalOn(FLOOR, date).orElseThrow();
    }

    /** The most a person's due-total can be, in force on the sheet's today; null when there is no cap. */
    public BigDecimal getCap() {
        return decimalOn(CAP, today).orElse(null);
    }

    /**
     * The due above which a claim dated on the date cannot be settled or approved without a proof; null when there is
     * no threshold then.
     */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return decimalOn(PROOF_THRESHOLD, date).orElse(null);
    }

    /** The days after its date a claim dated on the date of a grade without its own terms then is due by. */
    public int termsOn(LocalDate date) {
        return Integer.parseInt(valueOn(TERMS, date).orElseThrow());
    }

    /** The grade's own terms in force on the date; empty when it has none then (the sheet's terms apply). */
    public Optional<Integer> gradeTermsOn(String grade, LocalDate date) {
        return valueOn(gradeTermsKey(grade), date).map(Integer::parseInt);
    }

    /** The days after its date a claim dated on the date of a person of the grade is due by. */
    public int termsFor(String grade, LocalDate date) {
        return gradeTermsOn(grade, date).orElseGet(() -> termsOn(date));
    }

    /** The percent of its figure an overdue claim dated on the date gains for every full 30 days it is overdue. */
    public BigDecimal latePctOn(LocalDate date) {
        return decimalOn(LATE_PCT, date).orElseThrow();
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or after it. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /**
     * How a claim rounding by {@code date} rounds its live figures: half up when dated before the policy date (the
     * sheet's today when it has none), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate date) {
        return date.isBefore(policyDate != null ? policyDate : today) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The rate step: the amount at the percent, to two decimals rounded as a claim rounding by the date does. */
    public BigDecimal rateStep(BigDecimal amount, BigDecimal pct, LocalDate roundingDate) {
        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding(roundingDate));
    }

    /**
     * The late charge on a figure of an OPEN claim dated {@code date}: the late percent of the figure for every full
     * 30 days the sheet's today is past the claim's due-by (the late percent in force on its date), rounded as the
     * claim's date has it; zero when not overdue,
     * null (n/a) when the figure is.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
        if (figure == null) {
            return null;
        }
        long overdueDays = ChronoUnit.DAYS.between(dueBy, today);
        long periods = overdueDays <= 0 ? 0 : overdueDays / 30;
        return figure.multiply(latePctOn(date)).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, rounding(date));
    }

    /** The figure with its late charge added on top when the claim is OPEN; null (n/a) stays null. */
    public BigDecimal withLateCharge(BigDecimal figure, boolean open, LocalDate dueBy, LocalDate date) {
        return figure == null || !open ? figure : figure.add(lateCharge(figure, dueBy, date));
    }

    /** A due-total held down to the cap in force on the sheet's today; null (n/a), or no cap, leaves it as it is. */
    public BigDecimal capped(BigDecimal dueTotal) {
        BigDecimal cap = getCap();
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    /** A live due of a claim dated on the date raised to the floor in force on it; null (n/a) stays null. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        return due == null ? null : due.max(floorOn(date));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A dated setting's value on a sheet, in force from its from-date until the key's next from-date. */
@Entity
@Table(name = "dated_setting")
public class DatedSetting {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "sheet_id", nullable = false)
    private Sheet sheet;

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    /** The value as kept (a plain decimal or whole number); null: none (no clerk limit, no cap). */
    @Column(name = "setting_value")
    private String value;

    protected DatedSetting() {
    }

    DatedSetting(Sheet sheet, String key, LocalDate fromDate, String value) {
        this.sheet = sheet;
        this.key = key;
        this.fromDate = fromDate;
        this.value = value;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getValue() {
        return value;
    }

    void setValue(String value) {
        this.value = value;
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the people's claims on a sheet. A claim with no date is dated the sheet's today. A claim dated in a closed
 * period cannot be added, edited, deferred or change status. Only a DRAFT claim can be edited; a PENDING claim, waiting for a
 * steward to approve or reject it, is otherwise handled like an OPEN one. No claim
 * can be dated after the retirement date of its person. A claim whose due is above the proof threshold on its date
 * cannot be settled or approved without a proof. A claim with a negative amount is a correction: it must name,
 * by number, a SETTLED claim of the same person that it corrects, and its due has no floor and no late charge.
 */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateService rates;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final PeriodService periods;
    private final RoleService roles;
    private final SettingService settings;
    private final ClaimLogRepository logs;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
            Audit audit, RollupService rollup, PeriodService periods, RoleService roles, SettingService settings,
            ClaimLogRepository logs) {
        this.logs = logs;
        this.periods = periods;
        this.roles = roles;
        this.settings = settings;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /** The status logs of the sheet's claims by claim id, each oldest first. */
    public Map<Long, List<ClaimLog>> logs(String sheetId) {
        return logs.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(ClaimLog::getClaimId, Collectors.toList()));
    }

    /** The claim's status log, oldest first. */
    public List<ClaimLog> logOf(Claim claim) {
        return logs.findByClaimIdOrderByIdAsc(claim.getId());
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        LocalDate dated = dateOr(sheetId, date);
        periods.requireOpen(sheetId, dated);
        person.requireClaimable(dated);
        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
        claim.setCorrects(corrects);
        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
        // Due by its date plus the terms of its person's grade on that date, fixed from now on.
        claim.setDueBy(dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated), dated)));
        claim.setListed(sheets.nextListed(sheetId));
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    @Transactional
    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimNotEditableException(id, claim.getStatus());
        }
        LocalDate dated = dateOr(sheetId, date);
        // Neither out of nor into a closed period.
        periods.requireOpen(sheetId, claim.getDate(), dated);
        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
                .requireClaimable(dated);
        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setDate(dated);
        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Move a claim to another status, if its current one allows it; refused otherwise. A clerk settling a claim whose
     * due is above the clerk limit sends it to PENDING instead, for a steward to approve or reject.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING) {
            throw new ClaimStatusException(id, claim.getStatus(), status);
        }
        periods.requireOpen(sheetId, claim.getDate());
        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
        }
        // Four eyes: whoever opened a claim cannot also settle it.
        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ClaimSettledByOpenerException(id, user);
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        if (status == ClaimStatus.SETTLED) {
            requireProof(sheetId, person, claim);
        }
        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
            BigDecimal limit = settings.get(sheetId).getClerkLimit();
            BigDecimal due = withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                status = ClaimStatus.PENDING;
            }
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim) : "";
        claim.setStatus(status);
        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
        String number = claim.getNumber();
        if (status == ClaimStatus.OPEN) {
            number = nextNumber(sheetId, claim.getDate());
            claim.setNumber(number);
            claim.setOpenedBy(user);
        }
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        String event = switch (status) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        };
        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward other than its opener approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
     * its live figure.
     */
    @Transactional
    public Claim approve(String sheetId, String user, Long id) {
        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
        if (user.equals(claim.getOpenedBy())) {
            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        requireProof(sheetId, person, claim);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String due = settle(sheetId, person, claim);
        claim.setStatus(ClaimStatus.SETTLED);
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last statement
     * if that statement included it.
     */
    @Transactional
    public Claim reject(String sheetId, String user, Long id, String reason) {
        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.OPEN);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setStatus(ClaimStatus.OPEN);
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_REJECTED", user, person, saved) + numberOf(saved.getNumber())
                + " reason=" + reason);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
     * loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
     * retired before its date, or a user not a steward.
     */
    @Transactional
    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimReassignForbiddenException(id, user);
        }
        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
            throw new ClaimReassignException(id, "it is " + claim.getStatus());
        }
        if (claim.getPersonId().equals(toPersonId)) {
            throw new ClaimReassignException(id, "it is already that person's");
        }
        periods.requireOpen(sheetId, claim.getDate());
        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
        to.requireClaimable(claim.getDate());
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setPersonId(to.getId());
        claim.setStated(false, null);
        claim.setListed(sheets.nextListed(sheetId));
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
                + " from=" + from.getName() + " to=" + to.getName());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts in
     * no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim not OPEN, a
     * date not after today, or a closed period.
     */
    @Transactional
    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimDeferException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be deferred");
        }
        LocalDate today = sheets.today(sheetId);
        if (until == null || !until.isAfter(today)) {
            throw new ClaimDeferException(id, "it can only be deferred to a date after " + today);
        }
        periods.requireOpen(sheetId, claim.getDate());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setDeferredUntil(until);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_DEFERRED", user, person, saved) + numberOf(saved.getNumber())
                + " until=" + until);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
     * bound by no statement (today's rates, grades and floor, with its late charge as of today). Refused for any other
     * status, a closed period, or a user not a steward.
     */
    @Transactional
    public Claim resettle(String sheetId, String user, Long id) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimResettleForbiddenException(id, user);
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
        }
        periods.requireOpen(sheetId, claim.getDate());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String old = shownDue(sheetId, person, claim);
        BigDecimal figure = dueOf(sheetId, person, claim);
        claim.setSettledDue(settings.get(sheetId).withLateCharge(figure, !claim.isCorrection(), claim.getDueBy(),
                claim.getDate()));
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Add a proof to a claim, raising its proofs count by one. Refused for a SETTLED or VOID claim, or a closed period.
     */
    @Transactional
    public Claim addProof(String sheetId, String user, Long id) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ClaimProofException(id, "it is " + claim.getStatus() + ", a proof cannot be added");
        }
        periods.requireOpen(sheetId, claim.getDate());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        claim.addProof();
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", user, person, saved) + numberOf(saved.getNumber())
                + " proofs=" + saved.getProofs());
        return saved;
    }

    /**
     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date cannot be
     * settled or approved while it has no proof; refused then. A due of n/a is within any threshold.
     */
    private void requireProof(String sheetId, Person person, Claim claim) {
        BigDecimal threshold = settings.get(sheetId).proofThresholdOn(claim.getDate());
        if (threshold == null || claim.getProofs() > 0) {
            return;
        }
        BigDecimal due = withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
        if (due != null && due.compareTo(threshold) > 0) {
            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
                    + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
        }
    }

    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusException(id, claim.getStatus(), to);
        }
        periods.requireOpen(sheetId, claim.getDate());
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
        }
        return claim;
    }

    /**
     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
     * the rate on the claim's date) with its late charge frozen in; with no figure it stays live. Gives the due at the
     * end of its audit record.
     */
    private String settle(String sheetId, Person person, Claim claim) {
        BigDecimal figure = figureOf(sheetId, person, claim);
        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
                : figure.add(settings.get(sheetId).lateCharge(figure, claim.getDueBy(), claim.getDate()));
        claim.setSettledDue(settledDue);
        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
    }

    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
    private void log(String sheetId, String user, Person person, Claim claim) {
        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
                shownDue(sheetId, person, claim)));
    }

    /**
     * The claim's due as shown: the one fixed when it was settled, else its figure with its late charge on top; two
     * decimals, or n/a.
     */
    private String shownDue(String sheetId, Person person, Claim claim) {
        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
                : withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }

    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
    }

    /**
     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
     * for any other claim.
     */
    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            if (corrects != null) {
                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
            }
            return null;
        }
        if (corrects == null) {
            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
        }
        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
                .map(Claim::getDate)
                .orElseThrow(() -> new ClaimCorrectionException(
                        "Claim " + corrects + " is not a settled claim of the same person"));
    }

    /**
     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
     * date has the claim round, raised to the sheet's floor on its date unless it is a correction; null (n/a) with no rate.
     */
    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
        Sheet sheet = settings.get(sheetId);
        BigDecimal due = rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
                .orElse(null);
        return claim.isCorrection() ? due : sheet.floored(due, claim.getDate());
    }

    /**
     * The due with the late charge of an OPEN or PENDING claim overdue on the sheet's today added on top (none on a
     * correction, nor on a claim deferred on the sheet's today); null (n/a) stays null.
     */
    private BigDecimal withLateCharge(String sheetId, Claim claim, BigDecimal due) {
        Sheet sheet = settings.get(sheetId);
        return sheet.withLateCharge(due, claim.getStatus().isOpen() && !claim.isCorrection()
                && !claim.isDeferredOn(sheet.getToday()), claim.getDueBy(), claim.getDate());
    }

    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
    private static String record(String event, String user, Person person, Claim claim) {
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + " date=" + claim.getDate();
    }

    /** The claim's number at the end of an audit record, or nothing when it has none. */
    private static String numberOf(String number) {
        return number == null ? "" : " number=" + number;
    }

    /**
     * The number a claim dated on the date gets when opened: while the sheet numbers by period, the next in its
     * period's own sequence (X for no period); otherwise the next sheet-wide number.
     */
    private String nextNumber(String sheetId, LocalDate date) {
        if (settings.get(sheetId).numbersByPeriod()) {
            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
        }
        return String.valueOf(sheets.nextClaimNumber(sheetId));
    }

    private LocalDate dateOr(String sheetId, LocalDate date) {
        return date != null ? date : sheets.today(sheetId);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
